import React, { useEffect, useState } from 'react';
import axios from 'axios';

function App() {
  const [productos, setProductos] = useState([]);
  const [ventas, setVentas] = useState([]);
  const [nuevoProducto, setNuevoProducto] = useState({ 
    nombre: '', categoria: '', precioCompra: '', iva: 0, precioVenta: '', stockActual: '' 
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = () => {
    obtenerProductos();
    obtenerVentas();
  };

  const obtenerProductos = async () => {
    try {
      const res = await axios.get('http://localhost:8080/api/productos');
      setProductos(res.data);
    } catch (err) { console.error("Error al cargar productos", err); }
  };

  const obtenerVentas = async () => {
    try {
      const res = await axios.get('http://localhost:8080/api/ventas');
      setVentas(res.data);
    } catch (err) { console.error("Error al cargar ventas", err); }
  };

  const manejarVenta = async (id) => {
    try {
      await axios.post(`http://localhost:8080/api/ventas/${id}/1`);
      cargarDatos();
    } catch (err) {
      alert("⚠️ ¡Stock Agotado! No se puede realizar la venta.");
    }
  };

  const guardarProducto = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:8080/api/productos', nuevoProducto);
      setNuevoProducto({ nombre: '', categoria: '', precioCompra: '', iva: 0, precioVenta: '', stockActual: '' });
      cargarDatos();
    } catch (err) { alert("Error al registrar producto en el sistema."); }
  };

  // --- LÓGICA DE REPORTES FINANCIEROS (COP) ---
  const ingresosBrutos = ventas.reduce((acc, v) => acc + v.total, 0);

  const gananciaNeta = ventas.reduce((acc, v) => {
    const pOriginal = productos.find(p => p.nombre === v.productoNombre);
    if (pOriginal) {
      const costoConIva = pOriginal.precioCompra * (1 + (pOriginal.iva / 100));
      return acc + (v.total - (costoConIva * v.cantidad));
    }
    return acc;
  }, 0);

  // --- ESTILOS DARK PREMIUM ---
  const s = {
    container: { backgroundColor: '#0f0a06', color: '#d4a373', minHeight: '100vh', padding: '30px', fontFamily: "'Segoe UI', sans-serif" },
    header: { textAlign: 'center', marginBottom: '40px', borderBottom: '2px solid #3c2a1a', paddingBottom: '20px' },
    statsRow: { display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '20px', marginBottom: '30px' },
    statCard: { backgroundColor: '#1e160e', padding: '20px', borderRadius: '15px', textAlign: 'center', border: '1px solid #d4a373', boxShadow: '0 4px 15px rgba(0,0,0,0.5)' },
    mainGrid: { display: 'grid', gridTemplateColumns: '2fr 1.2fr', gap: '30px' },
    panel: { backgroundColor: '#1e160e', padding: '25px', borderRadius: '15px', border: '1px solid #3c2a1a' },
    input: { backgroundColor: '#0f0a06', color: '#fff', border: '1px solid #d4a373', padding: '12px', borderRadius: '8px', marginBottom: '10px', width: '95%' },
    btnVenta: { backgroundColor: '#d4a373', color: '#1e160e', padding: '8px 15px', border: 'none', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' },
    btnGuardar: { backgroundColor: '#4CAF50', color: '#fff', padding: '15px', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', width: '100%', marginTop: '10px' },
    table: { width: '100%', borderCollapse: 'collapse', marginTop: '10px' },
    th: { textAlign: 'left', padding: '12px', borderBottom: '2px solid #d4a373', color: '#d4a373' },
    td: { padding: '12px', borderBottom: '1px solid #3c2a1a', color: '#eee' }
  };

  return (
    <div style={s.container}>
      <div style={s.header}>
        <h1 style={{fontSize: '3rem', margin: 0}}>☕ EL PAISITA UP</h1>
        <p style={{color: '#8b735b', letterSpacing: '2px'}}>SISTEMA DE CONTROL FINANCIERO Y VENTAS</p>
      </div>

      {/* DASHBOARD DE MÉTRICAS */}
      <div style={s.statsRow}>
        <div style={s.statCard}>
          <h3 style={{margin: 0}}>Ventas Totales (Bruto)</h3>
          <h2 style={{color: '#fff'}}>${ingresosBrutos.toLocaleString('es-CO')} COP</h2>
        </div>
        <div style={s.statCard}>
          <h3 style={{margin: 0}}>Ganancia Real (Neta)</h3>
          <h2 style={{color: '#4CAF50'}}>${gananciaNeta.toLocaleString('es-CO')} COP</h2>
        </div>
        <div style={s.statCard}>
          <h3 style={{margin: 0}}>Productos en Stock</h3>
          <h2 style={{color: '#fff'}}>{productos.reduce((acc, p) => acc + p.stockActual, 0)} Unidades</h2>
        </div>
      </div>

      <div style={s.mainGrid}>
        {/* TABLA DE PRODUCTOS E INVENTARIO */}
        <div style={s.panel}>
          <h2 style={{marginTop: 0, color: '#d4a373'}}>📦 Inventario y Ventas Rápidas</h2>
          <table style={s.table}>
            <thead>
              <tr>
                <th style={s.th}>Producto</th>
                <th style={s.th}>Stock</th>
                <th style={s.th}>P. Venta</th>
                <th style={s.th}>IVA</th>
                <th style={s.th}>Acción</th>
              </tr>
            </thead>
            <tbody>
              {productos.map(p => (
                <tr key={p.id}>
                  <td style={s.td}>{p.nombre}</td>
                  <td style={{...s.td, color: p.stockActual < 5 ? '#ff4d4d' : '#fff'}}>
                    {p.stockActual} {p.stockActual < 5 && '⚠️'}
                  </td>
                  <td style={s.td}>${p.precioVenta.toLocaleString()}</td>
                  <td style={s.td}>{p.iva}%</td>
                  <td style={s.td}>
                    <button style={s.btnVenta} onClick={() => manejarVenta(p.id)}>VENDER 1</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* REGISTRO DE NUEVOS PRODUCTOS CON IVA */}
        <div style={s.panel}>
          <h2 style={{marginTop: 0, color: '#d4a373'}}>📋 Registro de Costos</h2>
          <form onSubmit={guardarProducto}>
            <label>Nombre del Producto</label>
            <input style={s.input} value={nuevoProducto.nombre} onChange={e => setNuevoProducto({...nuevoProducto, nombre: e.target.value})} required />

            <label>Categoría</label>
            <input style={s.input} value={nuevoProducto.categoria} onChange={e => setNuevoProducto({...nuevoProducto, categoria: e.target.value})} required />

            <div style={{display: 'flex', gap: '10px'}}>
              <div style={{flex: 1}}>
                <label>Costo Compra</label>
                <input style={s.input} type="number" value={nuevoProducto.precioCompra} onChange={e => setNuevoProducto({...nuevoProducto, precioCompra: parseFloat(e.target.value)})} required />
              </div>
              <div style={{flex: 1}}>
                <label>IVA (%)</label>
                <select style={s.input} value={nuevoProducto.iva} onChange={e => setNuevoProducto({...nuevoProducto, iva: parseFloat(e.target.value)})}>
                  <option value="0">0% (Exento)</option>
                  <option value="5">5% (Canasta)</option>
                  <option value="19">19% (General)</option>
                </select>
              </div>
            </div>

            <label>Precio Venta al Público</label>
            <input style={s.input} type="number" value={nuevoProducto.precioVenta} onChange={e => setNuevoProducto({...nuevoProducto, precioVenta: parseFloat(e.target.value)})} required />

            <label>Stock Inicial</label>
            <input style={s.input} type="number" value={nuevoProducto.stockActual} onChange={e => setNuevoProducto({...nuevoProducto, stockActual: parseInt(e.target.value)})} required />

            <button type="submit" style={s.btnGuardar}>GUARDAR EN INVENTARIO</button>
          </form>

          <div style={{marginTop: '20px', padding: '15px', backgroundColor: '#2c1e12', borderRadius: '10px', fontSize: '0.9rem'}}>
            <p>💡 <b>Tip de Ganancia:</b> Si compras a $1.000 con IVA 19%, tu costo real es $1.190. ¡Asegúrate de vender por encima de eso!</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default App;
